L["%d points to spend"] = "%d points à dépenser"
L["%d%% slower"] = "%d%% plus lent"
L["Active"] = "Actif"
L["Active build"] = "Build actif"
L["Experimental"] = "Expérimental"
L["Fastest"] = "Plus rapide"
